SQL_DOC.P_SQL:
SELECT 'DRBW' AS BUYER ,'KA' AS SITE ,WERKS AS PLANT ,EBELN AS LEGACY_PO_NO ,EBELP AS LEGACY_PO_SEQ ,'C' AS STATUS ,MATNR AS BUYER_ITEM_NO ,MENGE AS ITEM_QTY ,MEINS AS UNIT_MEASURE ,NETPR AS UNIT_PRICE ,ROUND(MENGE * NETPR,0) AS ITEM_AMT ,'$G_RS.PODAT$' AS ADD_DATE ,EINDT AS RD_DATE ,LGORT AS DELY_TO_LOCATION ,AFNAM AS PURCHASER_USER_ID ,utl_raw.cast_to_raw(NAME1) AS REQ_USER_NAME ,EKTEL AS REQ_USER_DEPT_NAME ,utl_raw.cast_to_raw(TXZ01) AS SPECIFICATION FROM SAPSR3.ZTMM088 WHERE EBELN = '$G_RS.EBELN$' ORDER BY MANDT, EBELN, EBELP
declare begin UPDATE SAPSR3.ZTMM087 SET OK_CODE = 'X' WHERE EBELN = '$G_RS.EBELN$' ;
UPDATE SAPSR3.ZTMM088 SET OK_CODE = 'X' WHERE EBELN = '$G_RS.EBELN$' AND TRIM(OK_CODE) IS NULL ; end;
